CREATE TABLE IF NOT EXISTS buildpulse_job_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),job_name TEXT NOT NULL,started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),finished_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'running' CHECK(status IN('running','ok','failed')),metrics JSONB NOT NULL DEFAULT '{}'::jsonb,error TEXT); ALTER TABLE buildpulse_job_runs ENABLE ROW LEVEL SECURITY; CREATE INDEX IF NOT EXISTS idx_buildpulse_job_runs_job_started ON buildpulse_job_runs(job_name,started_at DESC); REVOKE ALL ON buildpulse_job_runs FROM anon,authenticated;